scripts:
function Confirmar(titulo, message, tipo, tituloPrint) {


    swal({
        title: titulo,
        text: tituloPrint,
        icon: tipo,
        buttons: [
            'No!',
            'Yes!'
        ],
        dangerMode: true,
    }).then(function (isConfirm) {
        if (isConfirm) {
            swal({
                title: titulo,
                text: 'se esta Procesando la Informacion',
                icon: 'success'
            }).then(function () {
                Guardar();
            });
        } else {
            swal(titulo, message, tipo);
        }
    });
}

function grid_SelectionChanged() {
    var num = gvDatos.GetSelectedRowCount();
    if (num < 1) {
        document.getElementById("cpBody_bpagar").disabled = "disabled";
        document.getElementById("OpcionesDelivery").style.display = "none";

    } else {
        document.getElementById("cpBody_bpagar").disabled = "";
        document.getElementById("OpcionesDelivery").style.display = "";

    }
}
function FormaPago(e) {
    document.getElementById("cpBody_Guia").value = e;
    document.getElementById("cpBody_bCheckOut").click();
}




function GetLocation() {

    if ("geolocation" in navigator) { //check geolocation available 
        //try to get user current location using getCurrentPosition() method
        navigator.geolocation.getCurrentPosition(function (position) {
            console.log(position);
            $("#result").html("Su ubicación <br />Lat : " + position.coords.latitude + " </br>Lang :" + position.coords.longitude);
        });
    } else {
        console.log("Browser doesn't support geolocation!");
    }
};

function getDataSectores(s) {

    var TokenID = document.getElementById("cpBody_TokenID").value;
    $("#cpBody_Sectores").empty();
    $.ajax({
        type: "GET",
        url: "WebService1.asmx/Sectores",
        async: false,
        dataType: "json",
        data: "TokenID=" + TokenID + "&ProvinciaID=" + s,
        success: function (registro) {

            $.each(registro, function (key, registro) {
                $("#cpBody_Sectores").append('<option value=' + registro.codigo + '>' + registro.Nombre + '</option>');
            });
        },
        error: function (data) {
            alert('error');
        }
    });

}

$("#cpBody_sdelivery").on("click", function () {
    if ($("#cpBody_sdelivery")[0].checked) {
        document.getElementById("divDomicilio").style.display = "";
        $("#cpBody_sRecoger")[0].checked = false;
        $("#cpBody_sdelivery")[0].checked = true;

        GetLocation()();
    } else {
        document.getElementById("divDomicilio").style.display = "none";
        $("#cpBody_sRecoger")[0].checked = true;
        $("#cpBody_sdelivery")[0].checked = false;
    }
});

$("#cpBody_sRecoger").on("click", function () {
    if ($("#cpBody_sRecoger")[0].checked) {
        document.getElementById("divDomicilio").style.display = "none";
        $("#cpBody_sRecoger")[0].checked = true;
        $("#cpBody_sdelivery")[0].checked = false;
    } else {

        GetLocation();
        document.getElementById("divDomicilio").style.display = "";
        $("#cpBody_sRecoger")[0].checked = false;
        $("#cpBody_sdelivery")[0].checked = true;
    }
});
